steps.body:
A list is a chain of `Node` values, each with a `Val` and a `Next` pointer, and `head` points at the first node. Appending to the end would mean walking the whole list each time. Keep a `tail` pointer instead, and appending is constant time:

```go harness
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func main() {
	var head, tail *Node
	for _, x := range []int{1, 2, 3} {
		{{code}}
	}

	for n := head; n != nil; n = n.Next {
		fmt.Print(n.Val, " ")
	}
	fmt.Println()
}
```

```go
n := &Node{Val: x}
if head == nil {
	head = n
} else {
	tail.Next = n
}
tail = n
```

To insert after a node `n`, point the new node at `n.Next`, then point `n` at the new node. One line does both:

```go harness
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func main() {
	head := &Node{Val: 1, Next: &Node{Val: 2}}
	n := head
	{{code}}

	for n := head; n != nil; n = n.Next {
		fmt.Print(n.Val, " ")
	}
	fmt.Println()
}
```

```go
n.Next = &Node{Val: 0, Next: n.Next}
```

Deleting means relinking around a node: `prev.Next = cur.Next`. Once nothing points at the removed node, the garbage collector frees it. The first node has no `prev`, which usually needs a special case. A **dummy head** removes it: a fake node in front of the list gives every real node a predecessor.

```go harness
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func main() {
	head := &Node{Val: 1, Next: &Node{Val: 3, Next: &Node{Val: 4}}}
	{{code}}
	_, _ = prev, cur

	for n := head; n != nil; n = n.Next {
		fmt.Print(n.Val, " ")
	}
	fmt.Println()
}
```

```go
dummy := &Node{Next: head}
prev, cur := dummy, head
// ... unlink with prev.Next = cur.Next ...
head = dummy.Next
```

Two gotchas. Only move `prev` forward when you keep `cur`. And if you delete the last node, `tail` still points at it, so update `tail` before appending again.

example.code:
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func printList(head *Node) {
	if head == nil {
		fmt.Println("empty")
		return
	}
	for n := head; n != nil; n = n.Next {
		if n != head {
			fmt.Print(" -> ")
		}
		fmt.Print(n.Val)
	}
	fmt.Println()
}

func main() {
	var head, tail *Node
	for {
		var x int
		if _, err := fmt.Scan(&x); err != nil {
			break
		}
		n := &Node{Val: x}
		if head == nil {
			head = n
		} else {
			tail.Next = n
		}
		tail = n
	}

	for n := head; n != nil; n = n.Next {
		if n.Val%2 == 0 {
			n.Next = &Node{Val: 0, Next: n.Next}
			break // the new 0 is even too, so without break this inserts forever
		}
	}

	dummy := &Node{Next: head}
	prev, cur := dummy, head
	for cur != nil {
		if cur.Val == 3 {
			prev.Next = cur.Next // nothing in the list points at cur now
		} else {
			prev = cur
		}
		cur = cur.Next
	}
	head = dummy.Next
	printList(head)
}

