Reversing in place flips every `Next` pointer to point backwards. No new nodes are allocated: you only rewrite links. Walk with two pointers: `prev` (the reversed part, starting at `nil`) and `cur` (the part still to do):

```go harness
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func main() {
	head := &Node{Val: 1, Next: &Node{Val: 2, Next: &Node{Val: 3}}}
	{{code}}

	for n := head; n != nil; n = n.Next {
		fmt.Print(n.Val, " ")
	}
	fmt.Println()
}
```

```go
var prev *Node
cur := head
for cur != nil {
	next := cur.Next // save the rest first
	cur.Next = prev  // flip the link
	prev = cur
	cur = next
}
head = prev
```

The order matters. Once you write `cur.Next = prev`, the old `cur.Next` is gone, and so is the rest of the list. That is why `next` is saved first. When the loop ends, `cur` is `nil` and `prev` is the old tail, which is the new head.

Go evaluates the whole right side, and the `cur` in `cur.Next` on the left, before it assigns anything. So the loop body also fits on one line:

```go harness
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func main() {
	head := &Node{Val: 1, Next: &Node{Val: 2, Next: &Node{Val: 3}}}
	var prev *Node
	cur := head
	for cur != nil {
		{{code}}
	}
	head = prev

	for n := head; n != nil; n = n.Next {
		fmt.Print(n.Val, " ")
	}
	fmt.Println()
}
```

```go
cur.Next, prev, cur = prev, cur, cur.Next
```

It works, but a reader has to replay the assignment in their head to trust it. Prefer the four-line version, where each line does one thing.

example.code:
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func printList(head *Node) {
	for n := head; n != nil; n = n.Next {
		if n != head {
			fmt.Print(" -> ")
		}
		fmt.Print(n.Val)
	}
	fmt.Println()
}

func reverse(head *Node) *Node {
	var prev *Node
	cur := head
	for cur != nil {
		next := cur.Next // save the rest before cutting the link
		cur.Next = prev
		prev = cur
		cur = next
	}
	return prev
}

func main() {
	var head, tail *Node
	for {
		var x int
		if _, err := fmt.Scan(&x); err != nil {
			break
		}
		n := &Node{Val: x}
		if head == nil {
			head = n
		} else {
			tail.Next = n
		}
		tail = n
	}

	fmt.Print("before: ")
	printList(head)
	head = reverse(head)
	fmt.Print("after: ")
	printList(head)
}

