steps.body:
Many list problems are solved by two pointers moving at different speeds. Move `slow` one node and `fast` two nodes per step. When `fast` reaches the end, `slow` is in the middle:

```go harness
package main

import "fmt"

type Node struct {
	Val  int
	Next *Node
}

func main() {
	var head *Node
	for v := 5; v >= 1; v-- {
		head = &Node{Val: v, Next: head}
	}
	{{code}}
	fmt.Println("middle:", slow.Val)
}
```

```go
slow, fast := head, head
for fast != nil && fast.Next != nil {
	slow, fast = slow.Next, fast.Next.Next
}
```

For an even length this stops on the second middle. To stop on the first one, loop while `fast.Next != nil && fast.Next.Next != nil`, which needs a non-nil `head`.

To find the k-th node from the end without counting, move `lead` k nodes ahead, then move `lead` and `trail` together. When `lead` falls off the end, `trail` is k nodes behind it.

If a node links back to an earlier one, the list has a **cycle** and never reaches `nil`, so a plain `for n != nil` walk loops forever. Never walk a list that may have a cycle that way. Floyd's algorithm uses the same two speeds: inside a cycle the fast pointer gains one node per step, so it must land on the slow one. Compare the pointers with `==`, which checks for the same node, not the same value.

example.code:
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Node struct {
	Val  int
	Next *Node
}

func middle(head *Node) int {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow, fast = slow.Next, fast.Next.Next
	}
	return slow.Val
}

func kthFromEnd(head *Node, k int) int {
	lead, trail := head, head
	for i := 0; i < k; i++ {
		lead = lead.Next
	}
	for lead != nil {
		lead, trail = lead.Next, trail.Next
	}
	return trail.Val
}

func hasCycle(head *Node) bool {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow, fast = slow.Next, fast.Next.Next
		if slow == fast {
			return true
		}
	}
	return false
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var lines [][]int
	for scanner.Scan() {
		var nums []int
		for _, f := range strings.Fields(scanner.Text()) {
			n, err := strconv.Atoi(f)
			if err != nil {
				fmt.Println(err)
				return
			}
			nums = append(nums, n)
		}
		lines = append(lines, nums)
	}
	vals, k, p := lines[0], lines[1][0], lines[1][1]

	var head *Node
	nodes := make([]*Node, len(vals))
	for i := len(vals) - 1; i >= 0; i-- {
		head = &Node{Val: vals[i], Next: head}
		nodes[i] = head
	}

	fmt.Println("middle:", middle(head))
	fmt.Println("kth from end:", kthFromEnd(head, k))
	if p != -1 {
		nodes[len(nodes)-1].Next = nodes[p] // the tail now points back
	}
	fmt.Println("cycle:", hasCycle(head))
}

